mapper.select:
SELECT * FROM ( SELECT inner_q.*, ROWNUM AS RN FROM ( SELECT b.ID, b.TITLE, b.CONTENTS,
/* 썸네일 1개 */ (SELECT URL FROM BOARD_FILE bf WHERE bf.BOARD_ID = b.ID AND ROWNUM = 1) AS thumbnail,
/* 댓글 수 */ ( SELECT COUNT(*) FROM BOARD_COMMENT c WHERE c.BOARD_ID = b.ID ) AS commentCount,
/* 좋아요 수 */ ( SELECT COUNT(*) FROM BOARD_LIKE l WHERE l.BOARD_ID = b.ID ) AS likeCount,
b.VIEW_COUNT, b.CREATED_AT, b.UPDATED_AT, b.IS_NOTIFICATION,
u.UUID AS writerUid, u.NICKNAME AS writerNickname, u.PROFILE_URL AS writerProfileImage, u.BIO AS writerBio
FROM BOARD b LEFT JOIN USER_INFO u ON u.UUID = b.WRITER_UID
b.ID < #{cursorId}
ORDER BY b.ID DESC ) inner_q WHERE ROWNUM <= #{limit} ) WHERE RN > 0

mapper.insert:
INSERT INTO board(id, title, writer_uid, contents, is_notification)
VALUES (
board_seq.nextval, #{title}, #{writerUid}, #{contents}, #{isNotification}
)

    select board_seq.currval from dual

mapper.update:
UPDATE BOARD
SET TITLE           = #{title},
    CONTENT         = #{content},
    IS_NOTIFICATION = #{isNotification}
WHERE ID = #{id}

UPDATE BOARD
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE ID = #{id}
